{"hypotheses": [
  {
    "root_cause": "service:gridcast:forecast-pipeline",
    "mechanism": "A newly deployed pipeline version or configuration change altered forecast generation or plan-comparison logic, causing the new forecast to deviate more than 10% from the published plan.",
    "statement": "Self-originated change in the affected service is the most likely cause of a sudden, isolated forecast deviation."
  },
  {
    "root_cause": "service:gridcast:feature-service",
    "mechanism": "feature-service served stale, corrupted, or newly versioned features into forecast-pipeline, shifting model inputs enough to move the forecast more than 10% from plan.",
    "statement": "Upstream feature drift or version mismatch is the leading external-cause hypothesis."
  },
  {
    "root_cause": "service:gridcast:forecast-service",
    "mechanism": "forecast-service served a new or degraded model artifact or weights, producing materially different predictions that propagated to forecast-pipeline.",
    "statement": "A model or version change in the inference path is a plausible cause of sudden forecast deviation."
  },
  {
    "root_cause": "service:gridcast:planning-api",
    "mechanism": "planning-api returned an updated or incorrectly versioned published plan used as the comparison baseline, making the forecast appear off by more than 10%.",
    "statement": "A baseline or plan version mismatch could trigger the alert without a true forecast error."
  },
  {
    "root_cause": "service:gridcast:postgres",
    "mechanism": "postgres returned incomplete, stale, or incorrectly joined rows to forecast-pipeline or feature-service, causing the forecast to be computed from an inconsistent data snapshot.",
    "statement": "A database consistency or versioning issue is plausible but less likely to affect only forecast-pipeline."
  }
]}
